head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF30001";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_51", attr: "__html", fn: function () { return ([String(String(dma_map.get("regContnContn")).split("\\\\n").join("<br/>"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(String(dma_map.get("regContnContn")).split("\\\\n").join("<br/>"))) : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_contnId", fn: function () { return String((dma_pageContext.get("contnId") ?? "")); } },
        { childId: "__rb0", fn: function () { return String(String(dma_map.get("contnTitle")).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_goList();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":5
        ,"mmenu":1
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf30001' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf30001.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @event
 * @name scwin.td_32_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
 */
// TODO Stage2: 중복 정의 — as-is 에서 뒤 정의에 덮여 호출되지 않던 본문(JS 는 마지막 정의가 이긴다). 필요 없으면 삭제 — 원이름 td_32_oncellclick

/**
 * @method
 * @name td_32_oncellclick_1
 * @description td 32 oncellclick 1 처리
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.td_32_oncellclick_1 = async function (rowIndex, columnIndex, columnId) {
    try { if (columnId === 'attachFileNm') { const d = $c.util.getComponent('dlt_fileResult'); if (!d) { return; } await scwin.downloadFile(String(d.getCellData(rowIndex, "contnId")), String(d.getCellData(rowIndex, "attachFileNo"))); return; }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf30001.td_32_oncellclick' }); }
};

/**
 * @method
 * @name td_32_oncellclick
 * @description td_32 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.td_32_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_fileResult');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_fileResult */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.downloadFile(r["contnId"], r["attachFileNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'td_32.oncellclick' });
    }
};

/**
 * @method
 * @name btn_goList_onclick
 * @description btn_goList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goList_onclick = async function(e){
    try {
        await scwin.goList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf30001.btn_goList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_downloadFile
 * @description download File 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_downloadFile = async function (action) {
    try { return await $c.data.downFile(action ?? "/info/noticeDownload.do", "", ($c.util.getComponent("dma_downloadFileReq") ? $c.util.getComponent("dma_downloadFileReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_goList
 * @description go List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goList = async function () {
    const sbmOptions = {
        id: "tx_goList",
        method: "post",
        action: "/info/notice.do?method=noticeList",
        ref: "dma_goListReq",
        target: "dlt_fileResult=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name td_32_fmt_attachFileNm
 * @description td 32 fmt attach File Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.td_32_fmt_attachFileNm = function (data, formattedData, rowIndex, columnIndex) { return '<a href="javascript:void(0)"><strong>' + String(data) + '</strong></a>'; };

/**
 * @method
 * @name downloadFile
 * @description download File 처리
 * @param {*} contn_id contn_id
 * @param {*} attach_file_no attach_file_no
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.downloadFile = async function (contn_id, attach_file_no) {
    $c.util.getComponent('dma_downloadFileReq').set('method', 'noticeDownload');
    $c.util.getComponent("dma_downloadFileReq").set("contnId", contn_id);
    $c.util.getComponent("dma_downloadFileReq").set("attachFileNo", attach_file_no);
    await scwin.tx_downloadFile('/info/noticeDownload.do');
};

/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goList = async function () {
    await scwin.tx_goList();
};
